import{z as i,x as L,o as E,c as B,q as t,j as r,D as l,d as s,s as A,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"L 与 NL","description":"","frontmatter":{"title":"L 与 NL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nl-l-classes.md","filePath":"cs/nl-l-classes.md","lastUpdated":1791063341000}'),p={name:"cs/nl-l-classes.md"};function m(N,a,d,c,h,D){const n=L("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="l-与-nl" tabindex="-1">L 与 NL <a class="header-anchor" href="#l-与-nl" aria-label="Permalink to &quot;L 与 NL&quot;">​</a></h1><div class="epigraph"><p>对数工作空间：输入只读。L 是确定对数空间，NL 是非确定；可达性 NL 完全，Immerman–Szelepcsényi 让 NL 对补封闭。</p><footer>—— 据 Savitch；Immerman, 1988；Szelepcsényi, 1988；Sipser 整理</footer></div><p>上一课<a href="/cs/pspace-savitch">PSPACE 与 Savitch</a> 的平方在 \\(s=\\log n\\) 时把 NL 送进 \\(\\mathrm{DSPACE}(\\log^2 n)\\)，不是 L。缺口是对数空间这一层：L、NL、NL 完全问题 PATH，以及 NL \\(=\\) coNL。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工作带 \\(O(\\log n)\\)：只能放下指针、计数器，不能复制整份输入。输入带只读。L：确定。NL：非确定猜测（或等价地，有向图 \\(s\\)–\\(t\\) 可达 PATH）。PATH 在 NL：猜测后继顶点，写下当前顶点编号。NL 困难：对数空间归约把一般 NL 机的配置图交给 PATH。Savitch 只给 \\(\\mathrm{NL}\\subseteq\\mathrm{DSPACE}(\\log^2 n)\\)。\\(L\\stackrel{?}{=}NL\\) 开放。</p><p><span class="marginnote">直觉类比：对数空间像考试只发一张便签——题目（输入）只许看不许抄，便签上只够写几个指针和计数器；解题靠反复翻回原卷推算，而不是靠誊写数据。</span></p><p>Immerman–Szelepcsényi：非确定对数空间可数「不可达」——归纳计数可达顶点个数，对补封闭，\\(\\mathrm{NL}=\\mathrm{coNL}\\)。这与 NP 对 coNP 的开放形成对照。</p><h3 id="对数空间归约更严" tabindex="-1">对数空间归约更严 <a class="header-anchor" href="#对数空间归约更严" aria-label="Permalink to &quot;对数空间归约更严&quot;">​</a></h3><p>多项式时间归约会用太多空间。NL 完全用 \\(O(\\log n)\\) 工作空间的多一归约。不要用 Karp 归约直接当 NL 归约。</p><p><span class="marginnote">Immerman 与 Szelepcsényi 1988 独立证明 NL=coNL。Sipser 有配置图与归纳计数的课堂版。Reingold 后来证明无向可达在 L，本课点名不证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 PATH 的 NL 算法。说明配置图顶点可 \\(O(\\log n)\\) 写下。点名无向连通（Reingold）在 L，有向仍是 NL 的旗帜。不要把 BFS 原样搬进 L：队列太大。</p><p><span class="marginnote">数字实例：输入长 \\(n=10^6\\) 时 \\(\\log_2 n\\approx 20\\) 位——工作带大约只装得下两三个数组下标。这正是 BFS 搬不进 L 的原因：它的队列最长可达 \\(n\\) 项，本身就是线性空间。</span></p>',13)),(E(),r(o,null,{default:l(()=>[A(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LCLS%5B%22L%20%E7%A1%AE%E5%AE%9A%20log%20%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20NLCLS%5B%22NL%20%E9%9D%9E%E7%A1%AE%E5%AE%9A%22%5D%0A%20%20NLCLS%20--%3E%20PATH%5B%22PATH%20%E5%AE%8C%E5%85%A8%22%5D%0A%20%20NLCLS%20--%3E%20CONL%5B%22NL%20%3D%20coNL%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"主干图算法的 BFS 在 P；本课问的是工作空间，不是时间。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"空间小迫使算法流式、可重读输入。组合问题里「指针追逐」自然落在 NL。对补封闭意味着「不可达」同样有短非确定证明（证书形状与可达不同，靠计数）。NP 没有已知的对应定理。",-1)),a[6]||(a[6]=e("p",null,"\\(L\\subseteq NL\\subseteq P\\)，是否相等都开放。",-1)),a[7]||(a[7]=e("p",null,"输入只读迫使算法把输入当随机访问磁带，工作带只记指针。无向 \\(s\\)–\\(t\\) 可达在 L（Reingold），技巧是展开图上的 USTCON，本课不证。有向 PATH 仍是 NL 完全旗帜。\\(NL\\subseteq P\\) 因为配置图多项式大，可显式 BFS——时间与空间在这里分家。",-1)),(E(),r(o,null,{default:l(()=>[A(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E5%AF%B9%E6%95%B0%E7%A9%BA%E9%97%B4%E6%9C%BA%E5%99%A8%22%5D%20--%3E%20C%5B%22%E4%B8%80%E4%B8%AA%E9%85%8D%E7%BD%AE%EF%BC%9A%E7%8A%B6%E6%80%81%20%2B%20%E5%B7%A5%E4%BD%9C%E5%B8%A6%20%2B%20%E8%BE%93%E5%85%A5%E5%A4%B4%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20C%20--%3E%20G%5B%22%E9%85%8D%E7%BD%AE%E5%9B%BE%EF%BC%9A%E7%82%B9%E4%B8%BA%E9%85%8D%E7%BD%AE%EF%BC%8C%E8%BE%B9%E4%B8%BA%E4%B8%80%E6%AD%A5%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20G%20--%3E%20S%5B%22%E7%A9%BA%E9%97%B4%20log%20n%20%E2%87%92%20%E9%85%8D%E7%BD%AE%E5%8F%AA%E6%9C%89%E5%A4%9A%E9%A1%B9%E5%BC%8F%E4%B8%AA%22%5D%0A%20%20S%20--%3E%20Q%5B%22%E6%8E%A5%E5%8F%97%20%E2%87%94%20%E8%B5%B7%E5%A7%8B%E9%85%8D%E7%BD%AE%E5%8F%AF%E8%BE%BE%E6%8E%A5%E5%8F%97%E9%85%8D%E7%BD%AE%22%5D%0A%20%20Q%20--%3E%20R%5B%22PATH%20%E7%94%B1%E6%AD%A4%E6%88%90%E4%B8%BA%20NL%20%E5%AE%8C%E5%85%A8%E9%97%AE%E9%A2%98%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p>这张图回答：为什么图可达会恰好抓住整个 NL。把任意对数空间机器的「运行」改写成一张配置图，非确定猜测变成图里的分叉路，「存在接受的猜测」就成了「\\(s\\) 到 \\(t\\) 可达」——完全性归约也顺着这条路走。</p><p><span class="marginnote">常见误区：初学者容易以为 NL 的「非确定」只是并行加速。它有精确含义：接受当且仅当存在一条能到接受态的猜测路径；配置图视角把「猜路径」变成「图可达」，这正是 PATH 完全性的来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Reingold，不写 IS 定理的全部归纳。不引入 #L。后课默认：对数空间以 PATH 为完全问题；NL 对补封闭。下一课回到 NP：Cook–Levin，补上主干未写的 SAT 完全证明形状。</p><p>对数空间归约比 Karp 归约严：工作带不够抄整份输入。PATH 的完全性在这套归约下成立。对补封闭让「不可达」与「可达」同一类，这是 NP 没有的奢侈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>L / NL：只读输入 + 对数工作带。</li><li>PATH NL 完全；\\(L=NL\\) 开放。</li><li>Immerman–Szelepcsényi：\\(\\mathrm{NL}=\\mathrm{coNL}\\)。</li><li>出处：Savitch；Immerman, 1988；Szelepcsényi, 1988。</li></ul>',7))])}const u=i(p,[["render",m]]);export{S as __pageData,u as default};
